const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\r?\n/);
let lineIndex = 0;

function readLn() {
    return input[lineIndex++];
}

function readInt() {
    return Number(readLn());
}

function readStrings() {
    return readLn().split(' ');
}

function readInts() {
    return readStrings().map(Number);
}

function findLissPos() {
    const stones = readLn();
    const instructions = readLn();
    let curPos = 0;

    for (let i = 0; i < instructions.length; i++) {
        if (stones[curPos] === instructions[i]) {
            curPos++;
        }
    }

    curPos++;
    return curPos;
}

function main() {
    process.stdout.write(String(findLissPos()));
}

main();

